import{b as a,O as i,g as t,j as n}from"./chunks/framework.DSt9LnBW.js";const c=JSON.parse('{"title":"json-server服务配置","description":"开发测试中经常需要 mock 数据来调试接口，常见的做法有几种：手写 mock 拦截、用 Mock.js 生成随机数据、或者直接搭一个本地假服务。各有各的适用场景。json-server 属于最后一种——它能把你写好的一个 JSON 文件，瞬间变成一个功能齐全的 REST API 服务。支持 GET、POST、PUT、DELETE，跟真实接口的用法一模一样，只是数据存在本地。不需要写任何服务端代码，一个 JSON 文件就能跑起来。","frontmatter":{"date":"2026-06-14T00:00:00.000Z","tags":["工具","mock"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/tools/json-server-setup/index.md","filePath":"个人博客/工具篇/5.json-server服务配置.md","lastUpdated":1789534268000}'),e={name:"blog/tools/json-server-setup/index.md"};function p(l,s,h,o,k,d){return i(),t("div",null,[...s[0]||(s[0]=[n("",42)])])}const g=a(e,[["render",p]]);export{c as __pageData,g as default};
